"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,i,t)=>{t.r(i),t.d(i,{PAPERS:()=>a});let a=[{id:"2610.33568",title:"Trajectory2Gym: Decision-Grounded Compositional Interaction Synthesis for Tool-Use Agents",up:330,href:"https://arxiv.org/abs/2610.33568",abstract:"Successful tool-use trajectories are not necessarily useful supervision. Even successful interactions may underrepresent multi-step dependencies or contain actions that are unjustified by the information visible to the agent at decision time. We identify two coupled requirements for effective trajectory supervision: compositional coverage, so that important observation-action dependencies are represented, and decision grounding, so that each supervised action is supported by the learner-visible interaction history. We introduce Trajectory2Gym, which constructs executable interactions around un",pdfUrl:"https://arxiv.org/pdf/2610.33568",primaryCategory:"cs.CL",published:"2026-10-24T00:00:00Z"},{id:"2610.34662",title:"StreamVibe: Proactive Video Agents for Evolving User Intent",up:235,href:"https://arxiv.org/abs/2610.34662",abstract:'Vision-language models are shifting from offline passive understanding toward online proactive interaction. However, prevailing methods largely rely on explicit requests while miss the implicit user intent (e.g., "where should I click next?" while a user navigate a website), meanwhile fail to update the state simultaneously as user requests might update continuously. These limitations make them less suited to intent-aware interaction in practical. To address these challenges, we introduce StreamVibe-Bench, a new benchmark serving as testbed for user intent interaction, with 4.1K evaluation sam',pdfUrl:"https://arxiv.org/pdf/2610.34662",primaryCategory:"cs.CV",published:"2026-10-26T00:00:00Z"},{id:"2610.32285",title:"Trial by Trace: Benchmarking AI Agent Harnesses for Reliability and Failure Attribution",up:188,href:"https://arxiv.org/abs/2610.32285",abstract:"LLM agents are increasingly used to solve real-world problems, and their effectiveness depends on both the underlying models and the harnesses that support their operation. However, most existing benchmarks focus on model capabilities and overall agent performance, with limited attention to the evaluation of agent harnesses. To address this gap, we introduce TraceTrial-Bench, which organizes harness reliability into seven components covering context, execution, governance, lifecycle, observability, tools, and verification. We construct 95 expert-level, mechanism-oriented tasks with executable ",pdfUrl:"https://arxiv.org/pdf/2610.32285",primaryCategory:"cs.AI",published:"2026-10-23T00:00:00Z"},{id:"2610.34467",title:"DynaFlow: Learning Free-Form Multi-Agent Orchestration",up:182,href:"https://arxiv.org/abs/2610.34467",abstract:"Multi-agent systems often rely on predefined collaboration structures, limiting their ability to adapt to diverse task requirements. We introduce DynaFlow, a framework that integrates free-form executable workflow synthesis into the action space of the main agent. The agent decides when collaboration is needed and generates task-specific programs that coordinate sub-agents through sequential or parallel execution, structured information exchange, and verification. Execution results and traces inform subsequent actions, enabling the agent to adapt collaboration as reasoning progresses. We train",pdfUrl:"https://arxiv.org/pdf/2610.34467",primaryCategory:"cs.MA",published:"2026-10-25T00:00:00Z"},{id:"2610.33966",title:"InteractiveWorld: A Verifiable Human-Centric Environment for Building Better Interactive MLLM Assistants",up:109,href:"https://arxiv.org/abs/2610.33966",abstract:"People have long dreamed of an assistant that is always there to guide them and remind what they forget, from new dishes to lost keys. Powered by multimodal large language models (MLLMs), egocentric AI assistants on wearable devices are bringing this dream within reach: they see what the user sees and give instructions for user's physical work when necessary. However, testing such assistance is challenging and usually requires real people. The expensive and rare real interaction data leaves a key question unanswered: Can today's MLLMs truly help people in physical world? To answer this questio",pdfUrl:"https://arxiv.org/pdf/2610.33966",primaryCategory:"cs.HC",published:"2026-10-25T00:00:00Z"},{id:"2610.35845",title:"Work Agents: Systems, Capabilities, and Optimization",up:96,href:"https://arxiv.org/abs/2610.35845",abstract:"As foundation models evolve from information generation to digital work execution, agents are increasingly capable of completing complex tasks across tools, applications, and workflows. However, existing research lacks a unified perspective on how agents reliably accomplish delegated work. To address this gap, we present a work-centric, system-level perspective that views work agents as systems combining foundation models and runtime harnesses to execute tasks in stateful workspaces and deliver verifiable outcomes. We introduce two complementary dimensions, work persistence and work openness, ",pdfUrl:"https://arxiv.org/pdf/2610.35845",primaryCategory:"cs.LG",published:"2026-10-26T00:00:00Z"},{id:"2610.33956",title:"Continual Learning Exam: Benchmarking Long-Horizon RSI and Experiential Learning in LLM Agents",up:43,href:"https://arxiv.org/abs/2610.33956",abstract:"Continual learning is the ability of LLM agents to improve over time by acquiring, refining, and applying knowledge from experience while retaining useful prior knowledge. It is essential for agents learning over long time horizons, yet current evaluations largely assess individual task performance rather than improvement through accumulated experience. We introduce Continual Learning Exam (CLE), a large-scale benchmark developed by 50+ domain experts to measure experience-driven improvement in realistic professional workflows. CLE comprises 120 human-authored tasks, each organised as a five-l",pdfUrl:"https://arxiv.org/pdf/2610.33956",primaryCategory:"cs.LG",doi:"https://doi.org/10.1038/s41746-026-03348-0",year:2026,openalexId:"https://openalex.org/W7221316450",published:"2026-10-25T00:00:00Z"},{id:"2610.34415",title:"Spatial Audio Generation and Editing with Executable Plans and Self-Distilling Transfusion",up:38,href:"https://arxiv.org/abs/2610.34415",abstract:"Spatial audio authoring coordinates source decisions with soundfield synthesis. For editing, plans specify what to change and retain, while reference audio supplies further acoustic detail. We present AMBIT, a unified framework for native First-Order Ambisonics (FOA) generation and editing with three connected contributions. First, a shared Transfusion backbone couples autoregressive planning with rectified-flow rendering through executable ScenePlans that specify source content, activity, and 3D trajectories. For editing, the plan describes the full target scene, including retained sources; c",pdfUrl:"https://arxiv.org/pdf/2610.34415",primaryCategory:"cs.SD",published:"2026-10-25T00:00:00Z"},{id:"2610.33413",title:"AV-FABLE: Audio-Visual Manipulation Forensics in Long-Form Videos",up:33,href:"https://arxiv.org/abs/2610.33413",abstract:"Localized AI manipulations in long-form videos often affect brief events within otherwise authentic content, making video-level classification insufficient for forensic analysis. Existing audio-visual deepfake benchmarks largely focus on short talking-head clips, while long-form temporal forensics remains predominantly visual. We introduce AV-FABLE, a dual-timeline benchmark for sparse manipulations in open-scene long-form audio-visual videos. AV-FABLE contains 16,650 pristine--manipulated twin pairs (998 hours) created with 27 editing configurations, with separate audio and visual timelines t",pdfUrl:"https://arxiv.org/pdf/2610.33413",primaryCategory:"cs.CV",published:"2026-10-24T00:00:00Z"},{id:"2610.33512",title:"Eat Your Precision: Precision Objective Mitigates Reward Hacking in Rubric-based RL",up:27,href:"https://arxiv.org/abs/2610.33512",abstract:"Rubric-based rewards enable effective reinforcement learning on non-verifiable tasks. However, because these rewards are typically defined as a weighted measure of rubric coverage, models are trained primarily to maximize a recall objective. As a result, RL-trained models produce responses that are more complete but also more verbose and contain more unnecessary or factually incorrect content, leading them to be less preferred than responses from the base model. To address this issue, we present the FORK reward, which jointly optimizes recall and a novel precision objective, which requires eac",pdfUrl:"https://arxiv.org/pdf/2610.33512",primaryCategory:"cs.CL",published:"2026-10-24T00:00:00Z"},{id:"2610.32195",title:"Principia: Test-Time Hypotheses to Principle Construction for Scientific Discovery",up:21,href:"https://arxiv.org/abs/2610.32195",abstract:"Scientific discovery requires identifying the scientific principles underlying observed phenomena to guide further investigation. As these empirical principles are often unknown in complex discovery processes, they are constructed via a hypotheses-to-principle pipeline to obtain recurring causalities from progressively accumulated observations during test-time discovery. However, constructing this knowledge requires substantial domain expertise, time, and effort, making this translation stage a bottleneck for scientific discovery. To address this limitation, we propose Principia, an LLM-based ",pdfUrl:"https://arxiv.org/pdf/2610.32195",primaryCategory:"cs.LG",published:"2026-10-23T00:00:00Z"},{id:"2610.34238",title:"Δτ-Bench: Pushing Agents Toward a Moving Capability",up:21,href:"https://arxiv.org/abs/2610.34238",abstract:"In this paper, we introduce $Δτ$-Bench, an executable agent benchmark that models the structural evolution of large tool ecosystems. In $Δτ$-Bench, independently evolving services continually reshape how tasks can be accomplished: familiar tools may disappear or be replaced, while more efficient alternatives emerge amid overlapping functionality and noisy documentation. Against this moving capability frontier, we evaluate whether agents can proactively discover efficient tool-use paths and promptly revise their accumulated procedural knowledge, bringing together demands that existing benchmark",pdfUrl:"https://arxiv.org/pdf/2610.34238",primaryCategory:"cs.CL",published:"2026-10-25T00:00:00Z"},{id:"2610.33472",title:"Qwen-Image-PE: Learning Visual Design for Text-to-Image Prompt Enhancement",up:20,href:"https://arxiv.org/abs/2610.33472",abstract:"Learning visual design is essential for prompt enhancement (PE) to turn underspecified user requests into coherent visual specifications for text-to-image (T2I) generation. Existing methods preserve user intent and improve overall visual appeal, with less explicit emphasis on fine-grained design dimensions. To address this gap, we introduce Qwen-Image-PE, which learns visual design through two-stage training. Supervised fine-tuning with Caption-Based Reverse Distillation (CRD) uses dense captions of well-designed images as design supervision. Reinforcement learning with Groupwise Design Reward",pdfUrl:"https://arxiv.org/pdf/2610.33472",primaryCategory:"cs.CV",published:"2026-10-24T00:00:00Z"},{id:"2610.31635",title:"HiP3R: Hierarchical Pose Graphs for Long-Horizon 3D Reconstruction",up:19,href:"https://arxiv.org/abs/2610.31635",abstract:"Feed-forward models accurately estimate camera motion and 3D geometry from short video windows. However, computational and memory costs prevent direct inference on sequences containing thousands of frames. Long videos must therefore be processed as overlapping chunks. This division produces independent local reconstructions with inconsistent coordinate frames and duplicate estimates of shared cameras. Achieving global consistency requires propagating constraints from adjacent overlaps and distant revisits across the sequence. This requirement naturally motivates pose graph optimization. Howeve",pdfUrl:"https://arxiv.org/pdf/2610.31635",primaryCategory:"cs.CV",published:"2026-10-22T00:00:00Z"},{id:"2610.33169",title:"World-in-Context: Interactive Video World Modeling with In-Context Conditioning",up:18,href:"https://arxiv.org/abs/2610.33169",abstract:"Interactive video world models require coordinated control over viewing perspectives, character actions, and camera motion. Existing methods typically leave view modes implicit in text captions, conflate action with camera motion, and inject controls through fragmented architectural pathways that capture interdependencies only indirectly. In this work, we present World-in-Context, an interactive world modeling framework powered by In-Context Conditioning (ICC). Rather than relying on specialized conditioning pathways, World-in-Context unifies view, action, and camera controls into explicit tok",pdfUrl:"https://arxiv.org/pdf/2610.33169",primaryCategory:"cs.CV",published:"2026-10-23T00:00:00Z"},{id:"2610.35193",title:"Trustworthy Recursive Self-Improvement in the Era of Large Models: Foundation, Risks, Evaluation and Open Challenges",up:18,href:"https://arxiv.org/abs/2610.35193",abstract:"AI systems built around large models increasingly use experience and feedback to make persistent changes to models, prompts, memories, tools, and workflows. Recursive self-improvement (RSI) extends this process to inductive biases and to the mechanisms that govern future updates, which can themselves be revised and reused across improvement cycles. Yet self-modification alone does not guarantee trustworthy improvement. Reported gains may reflect flawed evaluations, previously acquired capabilities may deteriorate, and compliance with behavioral constraints may weaken. Compromised artifacts or ",pdfUrl:"https://arxiv.org/pdf/2610.35193",primaryCategory:"cs.AI",published:"2026-10-26T00:00:00Z"},{id:"2610.23928",title:"miniTE: Diagnosing and Bridging the Execution Gap in Native NVFP4 Reinforcement Learning",up:13,href:"https://arxiv.org/abs/2610.23928",abstract:"Native NVFP4 promises to accelerate reinforcement learning (RL) for large language models (LLMs), but achieving stable learning across separate training and sampling engines remains challenging. We show that matching model weights and numerical formats is insufficient to ensure consistent policy evaluation, highlighting the importance of cross-engine numerical execution. We introduce miniTE, a lightweight framework that combines execution diagnostics, cross-engine numerical alignment, and efficient native W4A4 (4-bit weights and activations) GEMM computation for LLM RL. It improves numerical e",pdfUrl:"https://arxiv.org/pdf/2610.23928",primaryCategory:"cs.LG",published:"2026-10-07T00:00:00Z"},{id:"2610.18683",title:"ProAS: A Progress-Aware Advantage Shaping Framework for Multi-Turn Agentic Reinforcement Learning",up:12,href:"https://arxiv.org/abs/2610.18683",abstract:"Reinforcement learning (RL) has emerged as the primary paradigm for optimizing Large Language Model (LLM) agents, yet efficient critic-free algorithms (e.g., GRPO) suffer from a fundamental uniform credit assignment dilemma that broadcasts trajectory-level advantages equally to all actions. Our analysis reveals that this uniformity inherently reinforces structurally unreasonable actions in preferred trajectories and ignores each action's downstream deviations in unpreferred ones. To resolve this without introducing critic overhead, we propose Progress-Aware Advantage Shaping (ProAS), a plug-an",pdfUrl:"https://arxiv.org/pdf/2610.18683",primaryCategory:"cs.LG",published:"2026-10-25T00:00:00Z"},{id:"2610.33024",title:"Evolving to Match Capabilities: Improving Harness Self-Evolution via Skill Adaptation",up:12,href:"https://arxiv.org/abs/2610.33024",abstract:"Harness self-evolution offers a practical route for LLM agents to improve from execution experience without updating model parameters. Its effectiveness depends on whether models can successfully act on the guidance provided by their harnesses. However, we find that harness benefits are not uniform across model capabilities: skills that improve stronger models can provide little benefit or even degrade performance for weaker ones. Across seven models and three benchmarks, we identify 103 task-skill pairs where skills improve GPT-5.6-luna by 31.1 points but degrade Gemma-4-E4B by 8.8 points. In",pdfUrl:"https://arxiv.org/pdf/2610.33024",primaryCategory:"cs.LG",published:"2026-10-10T00:00:00Z"},{id:"2610.35518",title:"S3AC: Stabilized, Selective, and Scalable Actor-Critic for LLM Reasoning",up:12,href:"https://arxiv.org/abs/2610.35518",abstract:"Critic-free methods are widely used in reinforcement learning with verifiable rewards (RLVR) for long chain-of-thought (CoT) reasoning, avoiding difficult and costly critic training. Common alternatives lack token-level credit assignment and typically rely on grouped rollouts to estimate prompt-specific baselines. A critic can address both limitations, but long-CoT critic training is hindered by insufficient coverage of trajectories with diverse lengths and early gradients dominated by the newly initialized value head. We introduce S3AC (Stabilized, Selective, and Scalable Actor-Critic) for LL",pdfUrl:"https://arxiv.org/pdf/2610.35518",primaryCategory:"cs.LG",published:"2026-10-26T00:00:00Z"},{id:"2610.31309",title:"Extreme Compression of Per-Layer Embeddings via Cross-Layer Latent Vector Quantization",up:10,href:"https://arxiv.org/abs/2610.31309",abstract:"Scaling embedding capacity alongside Transformer computation is an emerging trend in language models. This trend makes high compression rates increasingly useful. Hence, we study extreme compression of Per-Layer Embeddings (PLE), which follow this trend and account for 35.2% of the parameters of Gemma 4 E4B. At such rates, conventional quantizers give each token-layer vector its own code of only a few bytes. We instead develop OPTIC (Output-Path-fitted, Token-shared Indexed Codes), which stores one quantized code tuple per token and decodes it at every layer with a layer-specific affine decode",pdfUrl:"https://arxiv.org/pdf/2610.31309",primaryCategory:"cs.LG",published:"2026-10-22T00:00:00Z"},{id:"2610.33079",title:"Rethinking Video Storage for AI Training: Breaking Cross-Frame Dependencies for Efficient Random Access",up:10,href:"https://arxiv.org/abs/2610.33079",abstract:"Large-scale AI training increasingly relies on massive video datasets with random temporal sampling patterns. However, existing video storage paradigms are optimized for sequential playback and employ sophisticated inter-frame reference structures to maximize compression efficiency. When applied to the random-sampling workloads of AI training, these paradigms face substantial decoding-efficiency bottlenecks. Workarounds such as independent JPEG frames and short groups of pictures (GOPs) reduce decoding work at the cost of larger storage and transfer volumes. In this paper, we identify two sour",pdfUrl:"https://arxiv.org/pdf/2610.33079",primaryCategory:"cs.CV",published:"2026-10-21T00:00:00Z"},{id:"2610.33845",title:"Build, Don't Play: Self-Improving LLM Research Agents Develop a Hearthstone Battlegrounds AI That Rivals Top Players",up:10,href:"https://arxiv.org/abs/2610.33845",abstract:"Can LLM agents carry a hard real-world problem from raw data to a system that holds its own against people? We study this in Hearthstone Battlegrounds, an eight-player auto-battler with stochastic shops and battles, hidden information and nearly a thousand interacting cards. We present AutoTavern, a self-improving research system: specialised LLM research agents share a typed research memory, every claim passes verification gates, and live games close the loop, so the agents improve the simulator, opponents and policy and, from the same feedback, their own research process; a human sets goals ",pdfUrl:"https://arxiv.org/pdf/2610.33845",primaryCategory:"cs.AI",published:"2026-10-24T00:00:00Z"},{id:"2610.29915",title:"CausalAlign: Causal Alignment of Video Generation Models for Consistent Ego-Motion",up:9,href:"https://arxiv.org/abs/2610.29915",abstract:"Diffusion-based video generation models (VGMs) can produce visually plausible videos, yet their camera ego-motion often drifts over long horizons. Camera ego-motion determines how the viewpoint changes between frames and is essential for maintaining consistent geometry and trajectories. To address this problem, we propose CausalAlign, a causal alignment framework with two components. First, we diagnose how precise ego motion is represented, used, and retained within VGMs using linear probes and causal interventions, revealing a rise-and-fall pattern during denoising. Second, we strengthen ego-",pdfUrl:"https://arxiv.org/pdf/2610.29915",primaryCategory:"cs.CV",published:"2026-10-21T00:00:00Z"},{id:"W7171516088",title:"SpecBox: Speculative Sandbox Scheduling for Efficient LLM Agent Serving",up:0,href:"https://doi.org/10.48550/arxiv.2607.23933",crossrefDoi:"https://doi.org/10.1007/978-981-92-4805-6_13",year:2026,openalexId:"https://openalex.org/W7171516088",crossrefIssued:"2026-08-24"},{id:"W7204032694",title:"Do Not Let Sandboxes Sit Idle: Cross-Agent Sandbox Re-allocation for LLM Agents",up:0,href:"https://doi.org/10.1007/978-981-92-4805-6_13",doi:"https://doi.org/10.1007/978-981-92-4805-6_13",year:2026,openalexId:"https://openalex.org/W7204032694"},{id:"W7222522379",title:"Data Analysis Using LLMs: Tools, Sandboxes and Data Agents",up:0,href:"https://doi.org/10.20944/preprints202610.1601.v1",doi:"https://doi.org/10.20944/preprints202610.1601.v1",year:2026,openalexId:"https://openalex.org/W7222522379"}]}}]);